import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.CNDaxUod.js";const g=JSON.parse('{"title":"Drill-down","description":"","frontmatter":{},"headers":[],"relativePath":"contributor-guide/architecture/drill-down.md","filePath":"contributor-guide/architecture/drill-down.md"}'),r={name:"contributor-guide/architecture/drill-down.md"};function s(n,e,c,i,l,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="drill-down" tabindex="-1">Drill-down <a class="header-anchor" href="#drill-down" aria-label="Permalink to &quot;Drill-down&quot;">​</a></h1><p><code>StageDetailProvider</code> (<code>src/view/StageDetailContext.tsx</code>) replaces the legacy <code>openStageDetail</code> <code>window</code> <code>CustomEvent</code> with React context. Any component calls <code>useStageDetail().openStage(stageId)</code> to open <code>StageDetailDialog.tsx</code>, a Radix/shadcn <code>Dialog</code>, for that stage. The callers are StagePill, Timeline, StageTable, and TaskSkew&#39;s per-stage rows.</p><p>The legacy <code>drillDownToStage</code> force-expand-and-<code>scrollIntoView</code> event has no replacement. No code ever dispatched it, so it was dormant even before the migration, and it was dropped.</p><h2 id="plan-dot-serialization" tabindex="-1">Plan DOT serialization <a class="header-anchor" href="#plan-dot-serialization" aria-label="Permalink to &quot;Plan DOT serialization&quot;">​</a></h2><p><code>src/plan-dot.ts</code> (entry <code>planTreeToDot(planTree, { title })</code>, origin sparkDoctor&#39;s <code>SqlPlanDotWriter</code>) serializes a resolved <code>planTree</code> to a Graphviz DOT string. It is dependency-free string building. A first pass walks the tree assigning stable node ids and <code>label</code> (name, plus <code>detail</code> on a second line when it differs). A second pass emits the parent→child edges once ids are known. The graph is laid out <code>rankdir=BT</code>, leaves at the bottom, matching Spark&#39;s own plan orientation.</p><p>It carries no metric annotation: pure structure, matching sparkDoctor&#39;s own deferred roadmap item. A null plan returns an empty string. There is no download/export UI for this output anymore (removed); <code>PlanView.tsx</code> calls it only to decide whether a stage&#39;s plan tree can render as a graph at all, and a non-empty result gates the &quot;View plan graph&quot; button.</p><h2 id="plan-graph-view" tabindex="-1">Plan graph view <a class="header-anchor" href="#plan-graph-view" aria-label="Permalink to &quot;Plan graph view&quot;">​</a></h2><p><code>buildPlanGraphModel(planTree, opts)</code> (<code>src/plan-graph-model.ts</code>) flattens a resolved <code>planTree</code> into a <code>{ nodes, edges, segmentIndex, segmentCount, scope, segmentStageIds }</code> graph shape. <code>src/view/PlanGraphRoute.tsx</code> renders it with <code>@xyflow/react</code> (React Flow, pan/zoom/viewport/MiniMap) and <code>@dagrejs/dagre</code> (node layout, <code>src/view/plan-graph/dagre-layout.ts</code>, <code>rankdir: &#39;RL&#39;</code>).</p><p>Every <code>PlanGraphEdge</code> points <code>source: parentId, target: id</code> (parent/consumer → child/producer), and dagre places an edge&#39;s source at the higher-rank end. So <code>RL</code>, rather than the more intuitive-looking <code>LR</code>, is what lands reads/scans (targets, computed first) on the left and the final write/root (source) on the right, matching the left-to-right reading order of the plan&#39;s data flow. Each node&#39;s React Flow <code>Handle</code>s follow the same horizontal routing: <code>type=&quot;target&quot;</code> on <code>Position.Right</code> (its parent sits to the right) and <code>type=&quot;source&quot;</code> on <code>Position.Left</code> (its children sit to the left), rather than the top/bottom anchors a vertical <code>TB</code>/<code>BT</code> layout would use.</p><p><code>PlanGraphNode.tsx</code> renders every node at a fixed <code>NODE_WIDTH × NODE_HEIGHT</code> (220×90, also what dagre lays the graph out around) with <code>truncate</code>/<code>title</code> on every text field. An operator with an unusually long label/detail/metric string can&#39;t inflate the box and overlap neighbors; it ellipsizes instead, full text on hover.</p><p>Every <code>Exchange</code>-classified node is split into paired write/read halves sharing a <code>sourceNodeId</code>. The write half is grouped with its children&#39;s producer component; the read half is grouped with its parent&#39;s consumer component and carries <code>buildDurationMap</code>&#39;s duration share. The share stays on the original source Exchange node&#39;s attributed/read-side component rather than moving across the cut to the write half.</p><p>Default scope is <code>segment</code>: one Exchange-bounded slice of the plan, resolved via <code>computeSegments</code>/<code>zipSegmentsToStages</code> (<code>src/plan-duration-attribution.ts</code>, shared with <code>attributeStageDurationToPlan</code>). <code>computeSegments</code> gives every connected component a stable pre-order identity plus separate parent/depth/traversal metadata. The numeric identity does not encode Exchange-ancestor depth: <code>zipSegmentsToStages</code> orders by the explicit depth metadata (deepest first, plan traversal order for ties), and the display-only fallback uses component-tree edge distance to find the nearest strictly paired component.</p><p>The view has an opt-in &quot;Expand to full plan&quot; toggle gated by a 300-node confirmation dialog (<code>ExpandConfirmDialog.tsx</code>). A segment-lookup failure that would otherwise render an unguarded full plan is routed through the same guardrail rather than bypassing it. That same failure can also resolve to a full-scope model <em>below</em> the guardrail threshold, rendering immediately with no dialog and no <code>requestedScope</code> change. Since it&#39;s a permanent property of that stage&#39;s plan (<code>buildPlanGraphModel</code> is deterministic per <code>(planTree, stageId, appModel)</code>), there is no segment view left for that stage to switch back to. So the toggle, still correctly labeled &quot;Back to segment view&quot; per <code>model?.scope</code>, renders <code>disabled</code> rather than silently no-opping on click. Only the explicit-expand path (<code>requestedScope === &#39;full&#39;</code>) leaves it enabled.</p><p>Findings are never attached to individual plan nodes. No finding type in <code>src/detectors.ts</code> carries an unambiguous pointer to one specific plan-tree node: the closest, <code>smallFiles</code>/<code>duplicatePlanSubtree</code>, only carry a bare operator name string, ambiguous whenever it recurs (guaranteed for <code>duplicatePlanSubtree</code>, which matches a repeated structure by definition). Findings render at the stage level instead, which is always known precisely (<code>Finding.stageId</code>/<code>Finding.stageIds</code>).</p><p>The segment-level group box (<code>PlanGraphSegmentGroupNode.tsx</code>) always renders, even in the default single-stage view where it&#39;s the only box on screen. It is headered with its stage id (via <code>segmentStageIds</code>) and a duration chip, or an em-dash placeholder when the segment has no attributed duration. It also carries one <code>TagBadge</code> per finding on this stage, but only when there&#39;s no outer stage box to carry them instead (i.e. only in the default single-stage view).</p><p>The expanded full-plan view draws two nested layers of background group boxes (Dagre <code>compound: true</code> for spacing, <code>computeGroupBounds</code> for both): the same inner segment box described above, plus an outer solid tinted container per distinct stage id (<code>PlanGraphStageGroupNode.tsx</code>, <code>zIndex: -2</code> vs the segment layer&#39;s <code>-1</code>) merging every segment zipped to that stage, so a stage split across several Exchange-bounded segments still reads as one unit of work. In this expanded view the outer stage box, not the nested segment box, carries the stage&#39;s finding chips, since findings are stage-scoped rather than segment-scoped. Each stage box shows only findings matched to its own stage through <code>Finding.stageId</code> or <code>Finding.stageIds</code>; the default segment scope uses the same matching for its displayed stage.</p><p>The outer layer&#39;s own corner tag is positioned opposite the segment box&#39;s top-left header, because a stage with just one segment (the common case) would otherwise show the same &quot;Stage N&quot; header twice, stacked. <code>STAGE_GROUP_PADDING_Y</code> (64, no reserved header height) is sized to strictly exceed the segment layer&#39;s own reserved offset (<code>GROUP_PADDING + GROUP_HEADER_HEIGHT</code> = 56 at the top), while <code>STAGE_GROUP_PADDING_X</code> (32) is kept close to <code>GROUP_PADDING</code>&#39;s own 24px floor so the outer box doesn&#39;t visibly balloon sideways. Both still strictly contain the outer box around its nested segment box(es).</p><p>The view is reached via a &quot;View plan graph&quot; button in <code>PlanView.tsx</code>&#39;s toolbar, gated by the same <code>if (dot)</code> check described in &quot;Plan DOT serialization&quot; above. It opens a <code>planGraph: { active, stageId }</code> Zustand slice (<code>openPlanGraph</code>/<code>closePlanGraph</code>, <code>src/store/store.ts</code>) driving a top-level <code>AppRoutes</code> branch in <code>src/App.tsx</code>, modeled directly on the existing <code>comparison</code>/<code>RunComparisonRoute</code> full-takeover pattern.</p><p><code>buildPlanGraphModel</code>&#39;s output is memoized per <code>(activeFileId, stageId, scope)</code> in <code>PlanGraphRoute.tsx</code>, since <code>stageId</code> alone isn&#39;t unique across loaded runs and <code>applySnapshot</code> mutates <code>appModel</code> in place rather than replacing it (see <a href="./state-and-history.html#state-model">State model</a>). The memo cache is a module-level <code>Map</code>, so it survives across route open/close: re-opening the same stage in the same run reuses the cached model instead of rebuilding it. It must still be evicted on a fresh parse or reload. <code>resetModel()</code> (<code>store.ts</code>) bumps a <code>modelResetCount</code> counter for exactly this purpose, and <code>PlanGraphRoute.tsx</code> subscribes to it to clear the cache. A counter rather than a direct call, since <code>store.ts</code> has no view-layer imports anywhere else and importing a <code>.tsx</code> module there would invert that dependency direction.</p><h2 id="disclosure-hierarchy" tabindex="-1">Disclosure hierarchy <a class="header-anchor" href="#disclosure-hierarchy" aria-label="Permalink to &quot;Disclosure hierarchy&quot;">​</a></h2><p>The Summary/Context/Details 3-tier framing (collapsed lead metric → expanded widget body → per-stage <code>StageDetailDialog</code>) does not apply uniformly across the 15 registry widgets (<code>src/view/detector-registry.tsx</code>). 7 have a stage-anchored Details tier reachable via <code>StagePill</code>/<code>StagePillGroup</code>: TaskSkew, ShuffleIO, Spill, GcPressure, Failures, ExecutorTimeline, CachingOpportunity. The other 8 are app/sql-scope with no stage to drill into, by design, so they stop at Summary/Context: MemoryUtilization, JobFailures, ConfigAudit, PlanFindings, CacheUtilization, CoreUsageArea, AutoscalingChurn, IncompleteRun.</p><p>The 3-tier hierarchy is therefore not mandatory for every widget, and the current per-widget shape stays as-is: 2 tiers where there&#39;s no stage anchor, 3 where there is.</p><h2 id="reference-panel" tabindex="-1">Reference panel <a class="header-anchor" href="#reference-panel" aria-label="Permalink to &quot;Reference panel&quot;">​</a></h2><p>The topbar&#39;s &quot;Reference&quot; button and <code>DocsLink</code> (<code>src/view/DocsContext.tsx</code>) open a shadcn <code>Sheet</code> (<code>src/view/DocsSheet.tsx</code>, mounted once inside <code>DocsProvider</code>/<code>Dashboard.tsx</code>) that iframes a vendored, prebuilt docs chapter page (<code>vendor/spark-tuning-reference/chapters/spark/&lt;page&gt;.html</code>, referenced via <code>docs-config.js</code>&#39;s <code>docsUrl()</code>). <code>useDocs().open(anchor)</code> sets React state (<code>isOpen</code>, <code>anchor</code>); Radix/Base UI&#39;s <code>Sheet</code> owns the slide-in animation, focus trap, and outside-click/Escape dismissal. No more hand-rolled <code>.layout--split</code> class plus width-shrink CSS.</p><p>Upstream (<code>shuffle-works/spark-tuning-reference</code>) builds one committed HTML page per manifest entry (<code>chapters/spark/&lt;anchor&gt;.html</code>) instead of a single monolithic <code>index.html</code>; refresh the vendored copy with <code>npm run update-docs</code> (see <code>scripts/update-docs.mjs</code>), which shallow-clones upstream and vendors the whole <code>chapters/</code> tree rather than fetching named files one at a time. Most anchors the app links to are the page of the same name; a handful are in-page fragments on another entry&#39;s page instead (config-audit sub-findings and the metric glossary live on the <code>config</code>/<code>metrics</code> pages; the two bottleneck &quot;stage-*&quot; sub-anchors live on the page of the bottleneck that owns them): <code>docs-config.ts</code>&#39;s <code>pageForAnchor()</code> is the one place that resolves an anchor to its owning page. Production builds copy the vendored tree to <code>dist/vendor/spark-tuning-reference</code>; Vite&#39;s relative asset base keeps the app and docs usable when <code>dist/</code> is deployed under a URL subpath.</p><p><code>npm run update-docs</code> vendors upstream&#39;s <code>anchors.json</code> too (its SDOC-020 projection of the doc-anchor manifest) to <code>vendor/spark-tuning-reference/anchors.json</code>. <code>tests/doc-anchor-coverage.test.js</code> intersects it against every detector&#39;s <code>docAnchor</code> and warns (never fails) on dead links (detector points at an anchor <code>anchors.json</code> doesn&#39;t have) or orphaned Detector Catalog anchors (no detector points at them); see <code>scripts/doc-anchor-coverage.js</code>.</p><p><code>npm run update-docs</code> also vendors upstream&#39;s other build output not covered by the anchor-coverage gate, <code>landing.html</code> (the symptom-picker entry page), to <code>vendor/spark-tuning-reference/landing.html</code>: a plain looks-like-HTML check before overwriting the vendored copy.</p><p>Neither a vendor chapter page nor a docs-site (VitePress) page has a channel back to this app: both are plain static pages with no <code>postMessage</code> listener (upstream retired its <code>bridge.js</code> handshake once the monolithic page it served was dropped). <code>DocsSheet.tsx</code> therefore drives both the same way: any change to the resolved path or the theme reassigns the iframe&#39;s <code>src</code> outright, forcing a full reload. Since re-assigning the exact same <code>src</code> string wouldn&#39;t make the browser reload it, a <code>t=&lt;theme&gt;</code> marker is threaded into the query string ahead of the <code>#anchor</code> hash purely to change the string and force a real reload; neither page ever reads that param itself: each reads its light/dark preference once, from a localStorage key <code>ThemeProvider</code> keeps current (<code>vitepress-theme-appearance</code> for docs-site pages, <code>spark-tuning-reference-theme</code> for vendor chapter pages), the moment it boots.</p>',28)])])}const u=o(r,[["render",s]]);export{g as __pageData,u as default};
